/// Whether the policies in force let a request act on the queue it addresses — the gate
/// every operation that acts on a queue runs before it reports or changes anything — and
/// what a `Policy` attribute value has to look like to be stored at all.
pub mod authorization;
/// The data key a queue on a customer managed KMS key seals its messages under: where it
/// comes from, how long it is reused before this service calls KMS again, and what the
/// account's audit record says about each of those calls.
pub mod data_keys;
pub mod encryption;
/// The `AWS/SQS` series a queue publishes about itself: the backlog gauges it is sampled into
/// and the counters its data-plane calls are counted into, with the clock that keeps taking
/// those readings.
pub mod queue_depth_metrics;
/// Whether a send is a delivery another service is handing the queue as its own service
/// principal, on behalf of one of its own resources, rather than a client's own request.
pub mod service_delivery;

// The modules below are implementation detail: everything public in them is re-exported
// here, so callers name an item as `state::item` whichever file defines it.
mod address;
mod attributes;
mod clock;
mod digest;
mod limits;
mod message;
